1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { BuildOptions, PageMetadata } from './types.js';
4	import { PluginManager } from './plugin-manager.js';
5	import { Plugin, PluginContext, FileContext } from './plugin.js';
6	import { MarkdownPlugin } from './plugins/markdown-plugin.js';
7	import { TemplatePlugin } from './plugins/template-plugin.js';
8	
9	export class SiteGenerator {
10	  private contentDir: string;
11	  private outputDir: string;
12	  private templatesDir: string;
13	  private pluginManager: PluginManager;
14	
15	  constructor(options: BuildOptions, plugins?: Plugin[]) {
16	    this.contentDir = options.contentDir;
17	    this.outputDir = options.outputDir;
18	    this.templatesDir = options.templatesDir || './templates';
19	
20	    const defaultPlugins = [new MarkdownPlugin(), new TemplatePlugin()];
21	    const allPlugins = plugins ? [...defaultPlugins, ...plugins] : defaultPlugins;
22	    this.pluginManager = new PluginManager(allPlugins);
23	  }
24	
25	  private ensureDir(dirPath: string): void {
26	    if (!fs.existsSync(dirPath)) {
27	      fs.mkdirSync(dirPath, { recursive: true });
28	    }
29	  }
30	
31	  private getMarkdownFiles(): string[] {
32	    if (!fs.existsSync(this.contentDir)) {
33	      return [];
34	    }
35	
36	    return fs
37	      .readdirSync(this.contentDir)
38	      .filter((file) => file.endsWith('.md'))
39	      .sort();
40	  }
41	
42	  private generateIndexHtml(pages: PageMetadata[]): string {
43	    const pagesList = pages
44	      .map(
45	        (page) => `    <li>
46	      <a href="${this.escapeHtml(page.url)}">${this.escapeHtml(page.title)}</a>
47	      ${page.date ? `<span style="color: #666; margin-left: 10px;">${this.escapeHtml(page.date)}</span>` : ''}
48	      ${page.tags.length > 0 ? `<div style="margin-top: 5px;"><small>${page.tags.map((tag) => `<span style="display: inline-block; background: #eee; padding: 2px 8px; border-radius: 3px; margin-right: 5px;">${this.escapeHtml(tag)}</span>`).join('')}</small></div>` : ''}
49	    </li>`
50	      )
51	      .join('\n');
52	
53	    return `<!DOCTYPE html>
54	<html lang="en">
55	<head>
56	  <meta charset="UTF-8">
57	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
58	  <title>Static Site</title>
59	  <style>
60	    body {
61	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
62	      line-height: 1.6;
63	      max-width: 800px;
64	      margin: 0 auto;
65	      padding: 20px;
66	      color: #333;
67	    }
68	    h1 { margin-top: 0; }
69	    ul { list-style: none; padding: 0; }
70	    li {
71	      padding: 15px;
72	      border: 1px solid #eee;
73	      margin-bottom: 10px;
74	      border-radius: 5px;
75	    }
76	    li:hover { background: #f9f9f9; }
77	    a { color: #0066cc; text-decoration: none; }
78	    a:hover { text-decoration: underline; }
79	  </style>
80	</head>
81	<body>
82	  <h1>Pages</h1>
83	  ${pages.length > 0 ? `<ul>\n${pagesList}\n  </ul>` : '<p>No pages found.</p>'}
84	</body>
85	</html>`;
86	  }
87	
88	  private escapeHtml(text: string): string {
89	    return text
90	      .replace(/&/g, '&amp;')
91	      .replace(/</g, '&lt;')
92	      .replace(/>/g, '&gt;')
93	      .replace(/"/g, '&quot;')
94	      .replace(/'/g, '&#39;');
95	  }
96	
97	  getPluginManager(): PluginManager {
98	    return this.pluginManager;
99	  }
100	
101	  async build(): Promise<void> {
102	    this.ensureDir(this.outputDir);
103	
104	    const pluginContext: PluginContext = {
105	      contentDir: this.contentDir,
106	      outputDir: this.outputDir,
107	      templatesDir: this.templatesDir,
108	    };
109	
110	    await this.pluginManager.onStart(pluginContext);
111	    await this.pluginManager.beforeBuild(pluginContext);
112	
113	    const markdownFiles = this.getMarkdownFiles();
114	    const pages: PageMetadata[] = [];
115	
116	    for (const file of markdownFiles) {
117	      const filePath = path.join(this.contentDir, file);
118	      const content = fs.readFileSync(filePath, 'utf-8');
119	
120	      const fileContext: FileContext = {
121	        filename: file,
122	        filePath,
123	        content,
124	      };
125	
126	      await this.pluginManager.onFile(pluginContext, fileContext);
127	
128	      if (fileContext.html && fileContext.pageMetadata) {
129	        const outputPath = path.join(this.outputDir, fileContext.pageMetadata.url);
130	        fs.writeFileSync(outputPath, fileContext.html);
131	        pages.push(fileContext.pageMetadata);
132	      }
133	    }
134	
135	    const indexPath = path.join(this.outputDir, 'index.html');
136	    fs.writeFileSync(indexPath, this.generateIndexHtml(pages));
137	
138	    await this.pluginManager.afterBuild(pluginContext, pages);
139	    await this.pluginManager.onEnd(pluginContext);
140	
141	    console.log(`✓ Generated ${pages.length} page(s) to ${this.outputDir}`);
142	  }
143	}
