3	import * as path from 'path';
4	import { SiteGenerator } from './generator.js';
5	import { DevServer } from './dev-server.js';
6	import { loadConfig } from './config-loader.js';
7	
8	function parseArgs(args: string[]): { command: string; contentDir: string; outputDir: string; templatesDir: string; port: number } {
9	  let command = 'build';
10	  let contentDir = './content';
11	  let outputDir = './dist';
12	  let templatesDir = './templates';
13	  let port = 3000;
14	
15	  for (let i = 0; i < args.length; i++) {
16	    const arg = args[i];
17	
18	    if (!arg.startsWith('-')) {
19	      command = arg;
20	      continue;
21	    }
22	
23	    if (arg === '--content' && i + 1 < args.length) {
24	      contentDir = args[++i];
25	    } else if (arg === '--output' && i + 1 < args.length) {
26	      outputDir = args[++i];
27	    } else if (arg === '--templates' && i + 1 < args.length) {
28	      templatesDir = args[++i];
29	    } else if (arg === '--port' && i + 1 < args.length) {
30	      port = parseInt(args[++i], 10);
31	    }
32	  }
33	
34	  return { command, contentDir, outputDir, templatesDir, port };
35	}
36	
37	async function main(): Promise<void> {
38	  const args = process.argv.slice(2);
39	  const { command, contentDir, outputDir, templatesDir, port } = parseArgs(args);
40	
41	  const resolvedContentDir = path.resolve(contentDir);
42	  const resolvedOutputDir = path.resolve(outputDir);
43	  const resolvedTemplatesDir = path.resolve(templatesDir);
44	
45	  try {
46	    const plugins = await loadConfig(path.resolve('ssg.config.ts'));
47	
48	    if (command === 'build') {
49	      const generator = new SiteGenerator(
50	        {
51	          contentDir: resolvedContentDir,
52	          outputDir: resolvedOutputDir,
53	          templatesDir: resolvedTemplatesDir,
54	        },
55	        plugins
56	      );
57	
58	      await generator.build();
59	    } else if (command === 'serve') {
60	      const devServer = new DevServer({
61	        contentDir: resolvedContentDir,
62	        outputDir: resolvedOutputDir,
63	        templatesDir: resolvedTemplatesDir,
64	        port,
65	      });
66	
67	      await devServer.start();
68	
69	      process.on('SIGINT', async () => {
70	        console.log('\nShutting down server...');
71	        await devServer.stop();
72	        process.exit(0);
73	      });
74	    } else {
75	      console.error(`Unknown command: ${command}`);
76	      process.exit(1);
77	    }
78	  } catch (error) {
79	    console.error('Error:', error instanceof Error ? error.message : String(error));
80	    process.exit(1);
81	  }
82	}
83	
84	main();
