1	import { Plugin, PluginContext, FileContext } from './plugin.js';
2	import { PageMetadata } from './types.js';
3	
4	export class PluginManager {
5	  private plugins: Plugin[] = [];
6	
7	  constructor(plugins: Plugin[]) {
8	    this.plugins = plugins;
9	  }
10	
11	  async onStart(context: PluginContext): Promise<void> {
12	    for (const plugin of this.plugins) {
13	      if (plugin.onStart) {
14	        await plugin.onStart(context);
15	      }
16	    }
17	  }
18	
19	  async beforeBuild(context: PluginContext): Promise<void> {
20	    for (const plugin of this.plugins) {
21	      if (plugin.beforeBuild) {
22	        await plugin.beforeBuild(context);
23	      }
24	    }
25	  }
26	
27	  async onFile(context: PluginContext, file: FileContext): Promise<void> {
28	    for (const plugin of this.plugins) {
29	      if (plugin.onFile) {
30	        await plugin.onFile(context, file);
31	      }
32	    }
33	  }
34	
35	  async afterBuild(context: PluginContext, pages: PageMetadata[]): Promise<void> {
36	    for (const plugin of this.plugins) {
37	      if (plugin.afterBuild) {
38	        await plugin.afterBuild(context, pages);
39	      }
40	    }
41	  }
42	
43	  async onEnd(context: PluginContext): Promise<void> {
44	    for (const plugin of this.plugins) {
45	      if (plugin.onEnd) {
46	        await plugin.onEnd(context);
47	      }
48	    }
49	  }
50	
51	  getPlugins(): Plugin[] {
52	    return this.plugins;
53	  }
54	
55	  addPlugin(plugin: Plugin): void {
56	    this.plugins.push(plugin);
57	  }
58	
59	  removePlugin(pluginName: string): void {
60	    this.plugins = this.plugins.filter((p) => p.name !== pluginName);
61	  }
62	
63	  getPlugin(pluginName: string): Plugin | undefined {
64	    return this.plugins.find((p) => p.name === pluginName);
65	  }
66	}
