1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { Plugin, PluginContext, FileContext } from '../plugin.js';
4	import { TemplateEngine } from '../template-engine.js';
5	
6	export class TemplatePlugin implements Plugin {
7	  name = 'template';
8	  version = '1.0.0';
9	  private templateEngine: TemplateEngine | null = null;
10	
11	  async beforeBuild(context: PluginContext): Promise<void> {
12	    if (context.templatesDir && fs.existsSync(context.templatesDir)) {
13	      this.templateEngine = new TemplateEngine(context.templatesDir);
14	    }
15	  }
16	
17	  async onFile(context: PluginContext, file: FileContext): Promise<void> {
18	    if (!file.parsed) {
19	      return;
20	    }
21	
22	    const title = file.parsed.frontmatter.title || file.filename.replace('.md', '');
23	    const templateName = file.parsed.frontmatter.template
24	      ? String(file.parsed.frontmatter.template)
25	      : undefined;
26	    const layoutName = file.parsed.frontmatter.layout ? String(file.parsed.frontmatter.layout) : undefined;
27	
28	    file.pageMetadata = {
29	      filename: file.filename,
30	      title,
31	      date: file.parsed.frontmatter.date ? String(file.parsed.frontmatter.date) : undefined,
32	      tags: Array.isArray(file.parsed.frontmatter.tags)
33	        ? file.parsed.frontmatter.tags.map((tag) => String(tag))
34	        : [],
35	      url: file.filename.replace('.md', '.html'),
36	      template: templateName,
37	      layout: layoutName,
38	    };
39	
40	    file.html = this.renderPageWithTemplate(title, file.parsed.html, templateName, layoutName, file.parsed.frontmatter);
41	  }
42	
43	  private renderPageWithTemplate(
44	    title: string,
45	    content: string,
46	    templateName?: string,
47	    layoutName?: string,
48	    data?: Record<string, unknown>
49	  ): string {
50	    if (!this.templateEngine) {
51	      return this.generatePageHtml(title, content);
52	    }
53	
54	    const pageData = {
55	      title: this.escapeHtml(title),
56	      content,
57	      ...data,
58	    };
59	
60	    const template = templateName || 'page';
61	    const layout = layoutName || 'default';
62	
63	    try {
64	      if (this.templateEngine.hasLayout(layout)) {
65	        return this.templateEngine.renderPageTemplate(template, pageData, layout);
66	      }
67	    } catch {
68	      // Fall back to default HTML if template rendering fails
69	    }
70	
71	    return this.generatePageHtml(title, content);
72	  }
73	
74	  private generatePageHtml(title: string, content: string): string {
75	    return `<!DOCTYPE html>
76	<html lang="en">
77	<head>
78	  <meta charset="UTF-8">
79	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
80	  <title>${this.escapeHtml(title)}</title>
81	  <style>
82	    body {
83	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
84	      line-height: 1.6;
85	      max-width: 800px;
86	      margin: 0 auto;
87	      padding: 20px;
88	      color: #333;
89	    }
90	    h1, h2, h3, h4, h5, h6 { margin-top: 1.5em; }
91	    code {
92	      background: #f0f0f0;
93	      padding: 2px 6px;
94	      border-radius: 3px;
95	      font-family: 'Courier New', monospace;
96	    }
97	    pre {
98	      background: #f5f5f5;
99	      padding: 10px;
100	      border-radius: 5px;
101	      overflow-x: auto;
102	    }
103	    pre code { background: none; padding: 0; }
104	    a { color: #0066cc; text-decoration: none; }
105	    a:hover { text-decoration: underline; }
106	    .nav { margin-bottom: 20px; }
107	    .nav a { margin-right: 15px; }
108	  </style>
109	</head>
110	<body>
111	  <div class="nav">
112	    <a href="index.html">← Home</a>
113	  </div>
114	  <h1>${this.escapeHtml(title)}</h1>
115	  <div>${content}</div>
116	</body>
117	</html>`;
118	  }
119	
120	  private escapeHtml(text: string): string {
121	    return text
122	      .replace(/&/g, '&amp;')
123	      .replace(/</g, '&lt;')
124	      .replace(/>/g, '&gt;')
125	      .replace(/"/g, '&quot;')
126	      .replace(/'/g, '&#39;');
127	  }
128	}
